def font(size=22, bold=False):
    candidates = [r'C:\Windows\Fonts\arial.ttf', '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf']
    if bold:
        candidates = [r'C:\Windows\Fonts\arialbd.ttf', '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf']
    for f in candidates:
        if Path(f).exists(): return ImageFont.truetype(f, size)
    return ImageFont.load_default()

