        t=doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'; t.autofit=False
        for i,h in enumerate(headers):
            c=t.rows[0].cells[i]; c.text=h; shade(c,'DCE6F5'); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; set_cell_margins(c)
            for p in c.paragraphs: p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.line_spacing=1.05; p.alignment=WD_ALIGN_PARAGRAPH.CENTER
            for r in c.paragraphs[0].runs: r.bold=True; r.font.name='Times New Roman'; r.font.size=Pt(10)
        trPr=t.rows[0]._tr.get_or_add_trPr(); repeat=OxmlElement('w:tblHeader'); repeat.set(qn('w:val'),'true'); trPr.append(repeat)
        for row in rows:
            cells=t.add_row().cells
            t.rows[-1]._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
            for i,val in enumerate(row):
                cells[i].text=str(val); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; set_cell_margins(cells[i])
